// Copyright 2026 ReC Sandbox. Distributed under the terms in LICENSE.md at the repository root.#include "StdAfx.h"#include "CineGradeWidgets.h"#include <QDoubleSpinBox>#include <QGridLayout>#include <QHBoxLayout>#include <QLabel>#include <QMouseEvent>#include <QPainter>#include <QPushButton>#include <QSlider>#include <QVBoxLayout>#include <cmath>namespace CineCamGrade{// The three channel directions on the disc: red up, green and blue at 120 degrees clockwise from// each other, which is the RGB/CMY wheel Resolve, Baselight and every vectorscope overlay use -// yellow between red and green, cyan between green and blue, magenta between blue and red.//// deviation[c] = amplitude * ( y * cos(theta_c) + x * sin(theta_c) )//// The three cosines sum to zero for any direction, so the puck can never change the overall level// of the band: at the centre the deviation is exactly zero on all three channels, which is what// makes "the centre is neutral" a property of the mapping rather than a special case.static const float kChannelAngle[3] = { 0.0f, 2.0f * gf_PI / 3.0f, 4.0f * gf_PI / 3.0f };static Vec3 DeviationFromPos(const QPointF& pos, float amplitude){	Vec3 deviation(ZERO);	for (int c = 0; c < 3; ++c)	{		deviation[c] = amplitude * (float)(pos.y() * cos(kChannelAngle[c]) + pos.x() * sin(kChannelAngle[c]));	}	return deviation;}static QPointF PosFromDeviation(const Vec3& deviation, float amplitude){	if (amplitude <= 0.0f)		return QPointF(0.0, 0.0);	// Drop the common part: only the colour of the offset can be shown on a disc.	const float mean = (deviation.x + deviation.y + deviation.z) / 3.0f;	double x = 0.0;	double y = 0.0;	for (int c = 0; c < 3; ++c)	{		const float d = deviation[c] - mean;		x += d * sin(kChannelAngle[c]);		y += d * cos(kChannelAngle[c]);	}	// The projection above scales by 3/2, so undo that to land back on the unit disc.	const double scale = 2.0 / (3.0 * amplitude);	QPointF pos(x * scale, y * scale);	const double length = sqrt(pos.x() * pos.x() + pos.y() * pos.y());	if (length > 1.0)		pos /= length;	return pos;}// ---------------------------------------------------------------------------// CCineWheelDisc// ---------------------------------------------------------------------------CCineWheelDisc::CCineWheelDisc(QWidget* pParent)	: QWidget(pParent){	// Horizontally the disc takes whatever the dock gives it; the height is driven to match by	// CCineWheelControl::UpdateDiscSize, so the disc is square - and equally large on all three	// wheels - at every dock width without ever pushing its own minimum around.	setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Fixed);	setCursor(Qt::CrossCursor);	setToolTip(tr("Drag for hue and strength. Double-click or right-click to go back to neutral."));}void CCineWheelDisc::SetDeviation(const Vec3& deviation){	m_pos = PosFromDeviation(deviation, m_amplitude);	update();}Vec3 CCineWheelDisc::GetDeviation() const{	return DeviationFromPos(m_pos, m_amplitude);}QRectF CCineWheelDisc::DiscRect() const{	const qreal side = qMin(width(), height()) - 4.0;	return QRectF((width() - side) * 0.5, (height() - side) * 0.5, side, side);}void CCineWheelDisc::resizeEvent(QResizeEvent* pEvent){	QWidget::resizeEvent(pEvent);	// The disc is a picture of the mapping above, so it is built from the same formula rather than	// from a hand-tuned gradient: a pixel shows the colour its own offset would push towards.	const QRectF rect = DiscRect();	const int side = qMax(8, (int)rect.width());	// A resize that did not change the disc's diameter (only its box) keeps the picture it has:	// the loop below is O(side^2) and a dock drag delivers a resize every frame.	if (!m_wheelImage.isNull() && m_wheelImage.width() == side)		return;	QImage image(side, side, QImage::Format_ARGB32_Premultiplied);	image.fill(Qt::transparent);	const double radius = side * 0.5;	for (int py = 0; py < side; ++py)	{		for (int px = 0; px < side; ++px)		{			const double nx = (px + 0.5 - radius) / radius;			const double ny = (radius - py - 0.5) / radius;			const double length = sqrt(nx * nx + ny * ny);			if (length > 1.0)				continue;			const Vec3 hue = DeviationFromPos(QPointF(nx, ny), 1.0f);			const int r = (int)clamp_tpl(128.0f + hue.x * 127.0f, 0.0f, 255.0f);			const int g = (int)clamp_tpl(128.0f + hue.y * 127.0f, 0.0f, 255.0f);			const int b = (int)clamp_tpl(128.0f + hue.z * 127.0f, 0.0f, 255.0f);			// One pixel of feathering at the rim, so the disc has no staircase edge.			const double alpha = clamp_tpl((1.0 - length) * radius, 0.0, 1.0);			const int a = (int)(alpha * 255.0);			image.setPixel(px, py, qRgba((r * a) / 255, (g * a) / 255, (b * a) / 255, a));		}	}	m_wheelImage = image;}void CCineWheelDisc::paintEvent(QPaintEvent* /*pEvent*/){	QPainter painter(this);	painter.setRenderHint(QPainter::Antialiasing, true);	const QRectF rect = DiscRect();	if (!m_wheelImage.isNull())		painter.drawImage(rect, m_wheelImage);	painter.setBrush(Qt::NoBrush);	painter.setPen(QPen(QColor(24, 24, 24), 1.0));	painter.drawEllipse(rect);	const QPointF centre = rect.center();	const qreal radius = rect.width() * 0.5;	// A cross at the centre, so "neutral" is visible even when the puck sits on it.	painter.setPen(QPen(QColor(0, 0, 0, 110), 1.0));	painter.drawLine(QPointF(centre.x() - 4.0, centre.y()), QPointF(centre.x() + 4.0, centre.y()));	painter.drawLine(QPointF(centre.x(), centre.y() - 4.0), QPointF(centre.x(), centre.y() + 4.0));	const QPointF puck(centre.x() + m_pos.x() * radius, centre.y() - m_pos.y() * radius);	painter.setPen(QPen(QColor(255, 255, 255, 160), 1.0));	painter.drawLine(centre, puck);	painter.setPen(QPen(QColor(20, 20, 20), 1.5));	painter.setBrush(QColor(245, 245, 245));	painter.drawEllipse(puck, 4.5, 4.5);	if (!isEnabled())	{		painter.setPen(Qt::NoPen);		painter.setBrush(QColor(40, 40, 40, 140));		painter.drawEllipse(rect);	}}void CCineWheelDisc::SetFromPos(const QPoint& pos){	const QRectF rect = DiscRect();	const QPointF centre = rect.center();	const qreal radius = qMax(1.0, rect.width() * 0.5);	QPointF normalised((pos.x() - centre.x()) / radius, (centre.y() - pos.y()) / radius);	const double length = sqrt(normalised.x() * normalised.x() + normalised.y() * normalised.y());	if (length > 1.0)		normalised /= length;	m_pos = normalised;	update();	SignalChanged();}void CCineWheelDisc::Reset(){	SignalBeginEdit();	m_pos = QPointF(0.0, 0.0);	update();	SignalChanged();	SignalEndEdit();}void CCineWheelDisc::mousePressEvent(QMouseEvent* pEvent){	if (!isEnabled())		return;	if (pEvent->button() == Qt::RightButton)	{		Reset();		return;	}	if (pEvent->button() != Qt::LeftButton)		return;	m_dragging = true;	SignalBeginEdit();	SetFromPos(pEvent->pos());}void CCineWheelDisc::mouseMoveEvent(QMouseEvent* pEvent){	if (m_dragging)		SetFromPos(pEvent->pos());}void CCineWheelDisc::mouseReleaseEvent(QMouseEvent* pEvent){	if (m_dragging && pEvent->button() == Qt::LeftButton)	{		m_dragging = false;		SignalEndEdit();	}}void CCineWheelDisc::mouseDoubleClickEvent(QMouseEvent* pEvent){	if (isEnabled() && pEvent->button() == Qt::LeftButton)	{		m_dragging = false;		Reset();	}}// ---------------------------------------------------------------------------// CCineWheelControl// ---------------------------------------------------------------------------//! How small the disc may get before it stops being draggable, and how large it may get before it//! is only costing repaint time. Between the two it follows the dock.static const int kDiscMinSide = 72;static const int kDiscMaxSide = 208;//! Diameters are quantised to this, so the 16-odd pixels a scrollbar appearing takes away cannot//! start a grow/shrink ping-pong between the disc and the scroll area.static const int kDiscSideStep = 8;static QDoubleSpinBox* MakeSpin(double minValue, double maxValue, int decimals, double step){	QDoubleSpinBox* pSpin = new QDoubleSpinBox();	pSpin->setRange(minValue, maxValue);	pSpin->setDecimals(decimals);	pSpin->setSingleStep(step);	pSpin->setKeyboardTracking(false);	pSpin->setMinimumWidth(62);	return pSpin;}CCineWheelControl::CCineWheelControl(const QString& title, float neutral, float amplitude,                                     float masterMin, float masterMax, float masterNeutral, QWidget* pParent)	: QWidget(pParent)	, m_rgb(neutral, neutral, neutral)	, m_master(masterNeutral)	, m_neutral(neutral)	, m_masterMin(masterMin)	, m_masterMax(masterMax)	, m_masterNeutral(masterNeutral){	m_pDisc = new CCineWheelDisc(this);	m_pDisc->SetAmplitude(amplitude);	m_pMasterSlider = new QSlider(Qt::Vertical, this);	m_pMasterSlider->setRange(0, 1000);	m_pMasterSlider->setToolTip(tr("Master: the whole band at once."));	QLabel* pTitle = new QLabel(title, this);	pTitle->setAlignment(Qt::AlignCenter);	QFont titleFont = pTitle->font();	titleFont.setBold(true);	pTitle->setFont(titleFont);	QPushButton* pReset = new QPushButton(tr("Reset"), this);	pReset->setToolTip(tr("Back to neutral - the same as double-clicking the wheel."));	static const char* const szChannel[3] = { "R", "G", "B" };	QGridLayout* pNumbers = new QGridLayout();	pNumbers->setContentsMargins(0, 0, 0, 0);	pNumbers->setHorizontalSpacing(4);	pNumbers->setVerticalSpacing(2);	// The four fields follow the wheel's width instead of leaving a gap beside it.	pNumbers->setColumnStretch(1, 1);	for (int c = 0; c < 3; ++c)	{		// Wide enough for a real grade in either direction; the component itself does not clamp		// the triples, and TrackView keys are not clamped either.		m_pChannel[c] = MakeSpin(neutral - 2.0, neutral + 2.0, 4, 0.005);		pNumbers->addWidget(new QLabel(QString::fromLatin1(szChannel[c]), this), c, 0);		pNumbers->addWidget(m_pChannel[c], c, 1);	}	m_pMasterSpin = MakeSpin(masterMin, masterMax, 4, 0.005);	pNumbers->addWidget(new QLabel(tr("M"), this), 3, 0);	pNumbers->addWidget(m_pMasterSpin, 3, 1);	QHBoxLayout* pDiscRow = new QHBoxLayout();	pDiscRow->setContentsMargins(0, 0, 0, 0);	pDiscRow->addWidget(m_pDisc, 1);	pDiscRow->addWidget(m_pMasterSlider);	QVBoxLayout* pLayout = new QVBoxLayout(this);	pLayout->setContentsMargins(4, 4, 4, 4);	pLayout->setSpacing(4);	pLayout->addWidget(pTitle);	pLayout->addLayout(pDiscRow);	pLayout->addLayout(pNumbers);	pLayout->addWidget(pReset);	setLayout(pLayout);	connect(m_pDisc, &CCineWheelDisc::SignalBeginEdit, this, &CCineWheelControl::SignalBeginEdit);	connect(m_pDisc, &CCineWheelDisc::SignalEndEdit, this, &CCineWheelControl::SignalEndEdit);	connect(m_pDisc, &CCineWheelDisc::SignalChanged, this, &CCineWheelControl::OnDiscChanged);	for (int c = 0; c < 3; ++c)	{		connect(m_pChannel[c], static_cast<void (QDoubleSpinBox::*)(double)>(&QDoubleSpinBox::valueChanged),		        this, [this](double) { OnSpinChanged(); });	}	connect(m_pMasterSpin, static_cast<void (QDoubleSpinBox::*)(double)>(&QDoubleSpinBox::valueChanged),	        this, &CCineWheelControl::OnMasterSpinChanged);	connect(m_pMasterSlider, &QSlider::sliderPressed, this, &CCineWheelControl::SignalBeginEdit);	connect(m_pMasterSlider, &QSlider::sliderReleased, this, &CCineWheelControl::SignalEndEdit);	connect(m_pMasterSlider, &QSlider::valueChanged, this, &CCineWheelControl::OnMasterSliderChanged);	connect(pReset, &QPushButton::clicked, this, &CCineWheelControl::ResetAll);	RefreshWidgets();}void CCineWheelControl::SetValues(const Vec3& rgb, float master){	m_rgb = rgb;	m_master = master;	RefreshWidgets();}void CCineWheelControl::SetReadOnly(bool bReadOnly){	setEnabled(!bReadOnly);}void CCineWheelControl::resizeEvent(QResizeEvent* pEvent){	QWidget::resizeEvent(pEvent);	UpdateDiscSize();}void CCineWheelControl::UpdateDiscSize(){	// The disc is sized from the width the layout actually handed this control, minus the margins,	// the master slider beside it and the gap between the two - never from a size hint. The three	// controls share the panel's width equally, so the three discs stay the same size.	//	// Only the disc's MAXIMUM width is moved (its minimum stays at minimumSizeHint): if the	// minimum grew with the disc, this control could no longer shrink and the panel would be stuck	// at its widest ever size.	const int reserved = 8 + m_pMasterSlider->sizeHint().width() + 6;	int side = clamp_tpl(width() - reserved, kDiscMinSide, kDiscMaxSide);	side -= side % kDiscSideStep;	if (m_pDisc->maximumWidth() == side && m_pDisc->height() == side)		return;	m_pDisc->setMaximumWidth(side);	m_pDisc->setFixedHeight(side);}void CCineWheelControl::RefreshWidgets(){	m_updating = true;	m_pDisc->SetDeviation(m_rgb - Vec3(m_neutral, m_neutral, m_neutral));	for (int c = 0; c < 3; ++c)		m_pChannel[c]->setValue(m_rgb[c]);	m_pMasterSpin->setValue(m_master);	const float t = (m_masterMax > m_masterMin) ? (m_master - m_masterMin) / (m_masterMax - m_masterMin) : 0.0f;	m_pMasterSlider->setValue((int)(clamp_tpl(t, 0.0f, 1.0f) * 1000.0f + 0.5f));	m_updating = false;}void CCineWheelControl::OnDiscChanged(){	if (m_updating)		return;	const Vec3 deviation = m_pDisc->GetDeviation();	m_rgb = Vec3(m_neutral, m_neutral, m_neutral) + deviation;	m_updating = true;	for (int c = 0; c < 3; ++c)		m_pChannel[c]->setValue(m_rgb[c]);	m_updating = false;	SignalChanged();}void CCineWheelControl::OnSpinChanged(){	if (m_updating)		return;	for (int c = 0; c < 3; ++c)		m_rgb[c] = (float)m_pChannel[c]->value();	m_updating = true;	m_pDisc->SetDeviation(m_rgb - Vec3(m_neutral, m_neutral, m_neutral));	m_updating = false;	SignalBeginEdit();	SignalChanged();	SignalEndEdit();}void CCineWheelControl::OnMasterSliderChanged(int value){	if (m_updating)		return;	m_master = m_masterMin + (m_masterMax - m_masterMin) * (value / 1000.0f);	m_updating = true;	m_pMasterSpin->setValue(m_master);	m_updating = false;	SignalChanged();}void CCineWheelControl::OnMasterSpinChanged(double value){	if (m_updating)		return;	m_master = (float)value;	m_updating = true;	const float t = (m_masterMax > m_masterMin) ? (m_master - m_masterMin) / (m_masterMax - m_masterMin) : 0.0f;	m_pMasterSlider->setValue((int)(clamp_tpl(t, 0.0f, 1.0f) * 1000.0f + 0.5f));	m_updating = false;	SignalBeginEdit();	SignalChanged();	SignalEndEdit();}void CCineWheelControl::ResetAll(){	if (!isEnabled())		return;	SignalBeginEdit();	m_rgb = Vec3(m_neutral, m_neutral, m_neutral);	m_master = m_masterNeutral;	RefreshWidgets();	SignalChanged();	SignalEndEdit();}// ---------------------------------------------------------------------------// CCineFloatRow// ---------------------------------------------------------------------------CCineFloatRow::CCineFloatRow(const QString& label, float minValue, float maxValue, float neutral,                             int decimals, QWidget* pParent)	: QWidget(pParent)	, m_value(neutral)	, m_min(minValue)	, m_max(maxValue)	, m_neutral(neutral){	QLabel* pLabel = new QLabel(label, this);	pLabel->setMinimumWidth(120);	m_pSlider = new QSlider(Qt::Horizontal, this);	m_pSlider->setRange(0, 1000);	m_pSpin = MakeSpin(minValue, maxValue, decimals, (maxValue - minValue) / 400.0);	QHBoxLayout* pLayout = new QHBoxLayout(this);	pLayout->setContentsMargins(0, 0, 0, 0);	pLayout->setSpacing(6);	pLayout->addWidget(pLabel);	pLayout->addWidget(m_pSlider, 1);	pLayout->addWidget(m_pSpin);	setLayout(pLayout);	connect(m_pSlider, &QSlider::sliderPressed, this, &CCineFloatRow::SignalBeginEdit);	connect(m_pSlider, &QSlider::sliderReleased, this, &CCineFloatRow::SignalEndEdit);	connect(m_pSlider, &QSlider::valueChanged, this, &CCineFloatRow::OnSliderChanged);	connect(m_pSpin, static_cast<void (QDoubleSpinBox::*)(double)>(&QDoubleSpinBox::valueChanged),	        this, &CCineFloatRow::OnSpinChanged);	RefreshWidgets();}void CCineFloatRow::SetValue(float value){	m_value = value;	RefreshWidgets();}void CCineFloatRow::SetReadOnly(bool bReadOnly){	setEnabled(!bReadOnly);}void CCineFloatRow::RefreshWidgets(){	m_updating = true;	m_pSpin->setValue(m_value);	const float t = (m_max > m_min) ? (m_value - m_min) / (m_max - m_min) : 0.0f;	m_pSlider->setValue((int)(clamp_tpl(t, 0.0f, 1.0f) * 1000.0f + 0.5f));	m_updating = false;}void CCineFloatRow::OnSliderChanged(int value){	if (m_updating)		return;	m_value = m_min + (m_max - m_min) * (value / 1000.0f);	m_updating = true;	m_pSpin->setValue(m_value);	m_updating = false;	SignalChanged();}void CCineFloatRow::OnSpinChanged(double value){	if (m_updating)		return;	m_value = (float)value;	m_updating = true;	const float t = (m_max > m_min) ? (m_value - m_min) / (m_max - m_min) : 0.0f;	m_pSlider->setValue((int)(clamp_tpl(t, 0.0f, 1.0f) * 1000.0f + 0.5f));	m_updating = false;	SignalBeginEdit();	SignalChanged();	SignalEndEdit();}} // namespace CineCamGrade